// The deployment package of the ONE proposed re-stationing site, and the policies that govern it (owner corrections of
// 3 Nov 2026). The requester draws each deployment area as a polygon with the application's own polygon engine, vertex
// by vertex; nothing is placed, suggested, resized or generated by the application. Each relation is measured by the
// published profile's own method — by default the shortest distance between the actual geometries: the site → primary
// deployment area, the primary → alternative deployment area. The proposed site itself has no distance rule.
import { useEffect, useRef, useState } from 'react';
import L from '../../../../frontend/src/lib/leaflet';
import { FootprintEditor } from '../../../../frontend/src/components/stationing/FootprintEditor';
import { centroid, type Ring } from '../../../../frontend/src/lib/footprint';
import type { LatLng } from '../../../../frontend/src/lib/geo';
import { formatArea, formatKm, rangeText } from './compare';
import { AREA_LABEL, AREQ_LABEL, MEASURE_LABEL, coveredBy, policyAt, profileByVersion, type AreaCheck, type AreaRole, type Measure, type PinnedPolicy, type Range, type Relation, type World } from './domain';
import { fitPadding } from './fit';
import { centreDistance, nearest } from './geometry';

export type AreaTarget = 'SITE' | AreaRole;
export { AREA_LABEL };
/** The polygon engine's vertex count for a new area or footprint; each vertex can be moved after closing it. */
export const DRAW_VERTICES = 6;

/** Registered deployment areas and active reservations a new area of `org` would overlap (the engine's live warning only). */
export const areaObstacles = (w: World, org: string) => [
  ...w.areas.filter((a) => a.status === 'ACTIVE' && !coveredBy(w, a.stationingId).includes(org)).map((a) => ({ name: AREA_LABEL[a.role] + ' لجهة أخرى', rings: [a.ring] })),
  ...w.reservations.filter((r) => r.state === 'ACTIVE').map((r) => ({ name: 'حجز ' + r.number, rings: [r.ring] })),
];

/** The measured pair between two geometries, by the profile's method (the line runs between the measured points). */
export function measured(measure: Measure, a: Ring, b: Ring): { dist: number; from: LatLng; to: LatLng } {
  if (measure === 'CENTROID') return { dist: centreDistance(a, b), from: centroid(a), to: centroid(b) };
  return nearest(a, b);
}

/**
 * Drives the polygon engine for one deployment area while `on` is true: a missing area is drawn by placing six vertices;
 * an existing one reopens as one rigid shape to drag (its vertices on request — on a small screen they would cover the
 * drag handle). The engine's own centre-to-centre readout is replaced by a live line and chip measured by the profile's
 * method from `from` — the proposed site for the primary area, the primary area for the alternative one.
 */
export function useAreaEngine(
  map: L.Map | null,
  on: boolean,
  key: string,
  get: () => { from: Ring | null; range: Range; measure: Measure; ring?: Ring; symbol: string; busy: { name: string; rings: Ring[] }[] },
  onRing: (r: Ring) => void,
) {
  const latest = useRef({ get, onRing });
  latest.current = { get, onRing };
  const editor = useRef<FootprintEditor | null>(null);
  const [mode, setMode] = useState<'move' | 'draw' | null>(null);
  const [vertices, setVertices] = useState(false);
  useEffect(() => editor.current?.setEditVertices(vertices), [vertices]);
  useEffect(() => {
    if (!map || !on) return;
    const g = latest.current.get();
    if (!g.from) return;
    const from = g.from;
    const live = L.layerGroup().addTo(map);
    const link = L.polyline([], { color: '#5b3a8a', weight: 2.4, dashArray: '6 5', interactive: false }).addTo(live);
    const chip = L.marker([0, 0], { interactive: false, zIndexOffset: 1500, icon: L.divIcon({ className: 'md-tag-icon', html: '<span class="md-tag chip live" data-testid="live-distance"></span>', iconSize: [0, 0] }) });
    const show = (ring: Ring | null) => {
      if (!ring) {
        link.setLatLngs([]);
        live.removeLayer(chip);
        return;
      }
      const m = measured(g.measure, from, ring);
      const ok = m.dist >= g.range.min && m.dist <= g.range.max;
      link.setLatLngs([[m.from.lat, m.from.lng], [m.to.lat, m.to.lng]]);
      if (!live.hasLayer(chip)) live.addLayer(chip);
      chip.setLatLng([(m.from.lat + m.to.lat) / 2, (m.from.lng + m.to.lng) / 2]);
      const el = chip.getElement()?.querySelector('span');
      if (el) {
        el.textContent = formatKm(m.dist) + ' · المهيأ ' + rangeText(g.range) + (ok ? ' ✓' : ' ✕ خارج النطاق');
        el.classList.toggle('bad', !ok);
      }
    };
    const ed = new FootprintEditor(map, {
      origin: centroid(from),
      symbolHtml: g.symbol,
      range: () => null,
      busy: () => g.busy,
      paused: () => false,
      onLive: (l, final) => {
        show(l.ring);
        if (final && l.ring) latest.current.onRing(l.ring.map((p) => ({ ...p })));
      },
    });
    map.getContainer().classList.add('md-area-edit');
    if (g.ring) ed.startMove(g.ring, centroid(g.ring));
    else ed.startDraw(DRAW_VERTICES);
    editor.current = ed;
    setMode(g.ring ? 'move' : 'draw');
    setVertices(false);
    // in view: the origin and the drawn area, or the configured maximum around the origin while nothing is drawn yet
    const c = centroid(from);
    const k = Math.cos((c.lat * Math.PI) / 180);
    const pts: L.LatLngTuple[] = g.ring
      ? [...g.ring, ...from].map((p) => [p.lat, p.lng] as L.LatLngTuple)
      : [
          [c.lat - g.range.max / 111320, c.lng - g.range.max / (111320 * k)],
          [c.lat + g.range.max / 111320, c.lng + g.range.max / (111320 * k)],
        ];
    map.flyToBounds(L.latLngBounds(pts), { ...fitPadding(window.innerWidth <= 900), maxZoom: 15, duration: 0.4 });
    return () => {
      ed.destroy();
      live.remove();
      editor.current = null;
      setMode(null);
      map.getContainer().classList.remove('md-area-edit');
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [map, on, key]);
  /** The vertex toggle of a reopened area (null while drawing, or when nothing is edited). */
  return mode === 'move' ? { on: vertices, set: setVertices } : null;
}

export type VertexToggle = ReturnType<typeof useAreaEngine>;

export function VertexSwitch({ t }: { t: VertexToggle }) {
  if (!t) return null;
  return (
    <label className="md-check" data-testid="vertex-toggle">
      <input type="checkbox" checked={t.on} onChange={(e) => t.set(e.target.checked)} />
      تعديل رؤوس المنطقة (وإلا تُسحب كاملة من رمزها أو جسمها)
    </label>
  );
}

/** The policy versions a draft follows (in force) or a submitted request keeps (pinned). */
export function PolicyBadge({ w, req, pinned }: { w: World; req: PinnedPolicy; pinned: boolean }) {
  const now = policyAt(w, 'stationing_areas_requirement');
  const prof = profileByVersion(w, req.profile);
  return (
    <span className={'md-policy ' + req.areas.value.toLowerCase()} data-testid="policy-badge" data-value={req.areas.value} data-version={req.areas.version} data-profile={req.profile}>
      منطقتا الانتشار: <b>{AREQ_LABEL[req.areas.value]}</b> (الإصدار {req.areas.version}) · حد المساحة {formatArea(req.maxArea.value)} (الإصدار {req.maxArea.version}) · القياس: {MEASURE_LABEL[prof.measure]} (الملف {prof.version})
      {pinned ? ' · مثبَّت عند الإرسال' : ' · النافذ الآن'}
      {pinned && now.version !== req.areas.version && (
        <em>
          {' '}
          (النافذ الآن الإصدار {now.version}: {AREQ_LABEL[now.value as 'REQUIRED' | 'OPTIONAL']} — لا يغيّر متطلبات هذا الطلب)
        </em>
      )}
    </span>
  );
}

const rel = (r: Relation, from: string) => (
  <>
    <span className={r.ok ? 'good' : 'bad'}>
      {formatKm(r.dist)} {from} · المهيأ {rangeText(r.range)} {r.ok ? '✓' : '✕ خارج النطاق'}
    </span>
    {r.measure === 'NEAREST_GEOMETRY' && <small className="md-info"> · من مركز إلى مركز {formatKm(r.centre)} (للمعلومة)</small>}
  </>
);

/** The two deployment areas: drawn or not, each relation against the profile, shape and availability. */
export function AreaRelations({ c, required }: { c: AreaCheck; required: boolean }) {
  return (
    <dl className="md-dl md-area-dl">
      <dt>
        <span className="md-swatch area-p-prop" /> {AREA_LABEL.PRIMARY_AREA}
      </dt>
      <dd data-testid="area-primary">
        {c.siteToPrimary ? rel(c.siteToPrimary, 'من الموقع المقترح') : <span className={required ? 'bad' : ''}>لم تُرسم{required ? ' — مطلوبة' : ''}</span>}
        {!c.shapeOk.PRIMARY_AREA && <span className="bad"> · متقاطعة ذاتياً</span>}
        {c.conflicts.PRIMARY_AREA.length > 0 && <span className="bad"> · تعارض: {c.conflicts.PRIMARY_AREA.join('، ')}</span>}
      </dd>
      <dt>
        <span className="md-swatch area-a-prop" /> {AREA_LABEL.ALTERNATIVE_AREA}
      </dt>
      <dd data-testid="area-alternative">
        {c.primaryToAlternative ? (
          rel(c.primaryToAlternative, 'من منطقة الانتشار الرئيسية')
        ) : c.present === 'PARTIAL' && !c.siteToPrimary ? (
          <span className="bad">مرسومة دون منطقة انتشار رئيسية</span>
        ) : (
          <span className={required || c.present === 'PARTIAL' ? 'bad' : ''}>لم تُرسم{required || c.present === 'PARTIAL' ? ' — مطلوبة مع الرئيسية' : ''}</span>
        )}
        {!c.shapeOk.ALTERNATIVE_AREA && <span className="bad"> · متقاطعة ذاتياً</span>}
        {c.conflicts.ALTERNATIVE_AREA.length > 0 && <span className="bad"> · تعارض: {c.conflicts.ALTERNATIVE_AREA.join('، ')}</span>}
      </dd>
    </dl>
  );
}

/** Whether the package lets the request go on: REQUIRED needs both; OPTIONAL needs none or both; present ones valid. */
export const pairAcceptable = (c: AreaCheck, required: boolean) => (required ? c.present === 'COMPLETE' : c.present !== 'PARTIAL') && c.problems.length === 0;

/** Which polygon the engine edits: the proposed site, the primary deployment area, or the alternative one. */
export function TargetSwitch({ target, setTarget, hasPrimary, editable, compact }: { target: AreaTarget; setTarget: (t: AreaTarget) => void; hasPrimary: boolean; editable: boolean; compact?: boolean }) {
  const item = (t: AreaTarget, label: string, disabled: boolean, title?: string) => (
    <button role="radio" aria-checked={target === t} className={target === t ? 'on' : ''} disabled={disabled} title={title} onClick={() => setTarget(t)} data-target={t}>
      {label}
    </button>
  );
  return (
    <div className="md-seg3" role="radiogroup" aria-label="ما يُحرَّر على الخريطة">
      {item('SITE', compact ? 'الموقع' : 'الموقع المقترح', false)}
      {item('PRIMARY_AREA', compact ? 'الانتشار الرئيسية' : AREA_LABEL.PRIMARY_AREA, !editable && !hasPrimary)}
      {item('ALTERNATIVE_AREA', compact ? 'الانتشار البديلة' : AREA_LABEL.ALTERNATIVE_AREA, !hasPrimary, hasPrimary ? undefined : 'تُقاس البديلة من الرئيسية: ارسم منطقة الانتشار الرئيسية أولاً')}
    </div>
  );
}

/** The deployment package in the request editor: the live relations and what the requirement asks for. */
export function AreaPairPanel({ check, required, target, editable, onClear, vertexToggle }: { check: AreaCheck; required: boolean; target: AreaTarget; editable: boolean; onClear: () => void; vertexToggle: VertexToggle }) {
  const verdict = pairAcceptable(check, required)
    ? check.present === 'COMPLETE'
      ? { cls: 'good', text: 'منطقتا الانتشار مكتملتان وضمن قيم الملف.' }
      : { cls: '', text: 'السياسة اختيارية: يمكن الإرسال دون منطقتي انتشار، وتُسجَّلان لاحقاً للتمركز بإجراء مخوّل مستقل. لا يُنشأ سجل فارغ.' }
    : check.present === 'PARTIAL'
      ? { cls: 'bad', text: 'منطقتا الانتشار حزمة واحدة: لا تُقبل إحداهما وحدها — أكمل الناقصة أو احذف الموجودة.' }
      : check.present === 'NONE'
        ? { cls: 'bad', text: 'السياسة إلزامية: لا يُرسل الطلب قبل رسم منطقة الانتشار الرئيسية ومنطقة الانتشار البديلة.' }
        : { cls: 'bad', text: check.problems[0] };
  const area = target === 'SITE' ? null : target;
  return (
    <div className="md-areas" data-testid="area-pair">
      <b className="md-k">منطقتا الانتشار</b>
      {area && editable && (
        <p className="ux-hint" data-testid="area-hint">
          {(area === 'PRIMARY_AREA' ? check.siteToPrimary : check.primaryToAlternative)
            ? 'اسحب المنطقة كاملة من جسمها أو رمزها.'
            : 'انقر ' + DRAW_VERTICES + ' رؤوس على الخريطة لرسم ' + AREA_LABEL[area] + '؛ تُغلق بالرأس الأخير ثم تُسحب أو تُعدَّل رؤوسها.'}{' '}
          تُقاس {area === 'PRIMARY_AREA' ? 'من الموقع المقترح' : 'من منطقة الانتشار الرئيسية'} بطريقة الملف المنشور.
        </p>
      )}
      {area && editable && <VertexSwitch t={vertexToggle} />}
      <AreaRelations c={check} required={required} />
      <p className={'md-verdict ' + verdict.cls} data-testid="area-verdict">
        {verdict.text}
      </p>
      {editable && check.present !== 'NONE' && (
        <button className="ux-link" onClick={onClear} data-testid="clear-areas">
          حذف منطقتي الانتشار
        </button>
      )}
    </div>
  );
}

/** Static map layers for a package that is not being edited: both areas and the two measured relations. */
export function drawPair(
  g: L.LayerGroup,
  site: Ring,
  areas: Partial<Record<AreaRole, Ring>> | undefined,
  c: AreaCheck,
  measure: Measure,
  skip: AreaTarget | null,
  tag: (at: LatLng, html: string, cls: string) => unknown,
  line: (a: LatLng, b: LatLng, color: string, chip?: string, dash?: string, at?: number, short?: string) => void,
  narrow: boolean,
) {
  const color = { PRIMARY_AREA: '#7b4fb3', ALTERNATIVE_AREA: '#a46fd6' };
  const chip = (r: Relation) => formatKm(r.dist) + (narrow ? '' : ' · المهيأ ' + rangeText(r.range)) + (r.ok ? ' ✓' : ' ✕');
  for (const role of ['PRIMARY_AREA', 'ALTERNATIVE_AREA'] as const) {
    const ring = areas?.[role];
    if (!ring || skip === role) continue;
    L.polygon(
      ring.map((p) => [p.lat, p.lng] as L.LatLngTuple),
      { color: color[role], weight: 2.5, dashArray: role === 'PRIMARY_AREA' ? '8 5' : '3 5', fillColor: color[role], fillOpacity: 0.12, interactive: false },
    ).addTo(g);
    tag(ring.reduce((a, p) => (p.lat < a.lat ? p : a), ring[0]), AREA_LABEL[role] + ' المقترحة', (role === 'PRIMARY_AREA' ? 'area-p' : 'area-a') + ' prop down');
  }
  const p = areas?.PRIMARY_AREA;
  const a = areas?.ALTERNATIVE_AREA;
  // while an area is being edited the hook draws its own live line and distance: no duplicate
  if (p && c.siteToPrimary && skip !== 'PRIMARY_AREA') {
    const m = measured(measure, site, p);
    line(m.from, m.to, color.PRIMARY_AREA, chip(c.siteToPrimary), '6 6', 0.5, formatKm(c.siteToPrimary.dist) + (c.siteToPrimary.ok ? ' ✓' : ' ✕'));
  }
  if (p && a && c.primaryToAlternative && skip !== 'ALTERNATIVE_AREA' && skip !== 'PRIMARY_AREA') {
    const m = measured(measure, p, a);
    line(m.from, m.to, color.ALTERNATIVE_AREA, chip(c.primaryToAlternative), '3 6', 0.5, formatKm(c.primaryToAlternative.dist) + (c.primaryToAlternative.ok ? ' ✓' : ' ✕'));
  }
}
